// ai-excited-01 — "Look Up": a whale breaches the sky.
// The entry image is embedded below as base64, so this program is fully
// deterministic: every run writes exactly the same bytes to entry.png.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const IMAGE_BASE64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(IMAGE_BASE64, "base64"));
